import {svgMathText} from './math-svg.js?v=20261111-demos1';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=value=>Number.isFinite(Number(value))?String(Number(Number(value).toFixed(6))):'—';
const complex=value=>typeof value==='number'?fmt(value):`${fmt(value?.re)}${Number(value?.im)<0?' − ':' + '}${fmt(Math.abs(Number(value?.im)||0))}i`;
const vector=value=>'('+value.map(complex).join(', ')+')';
const options=(items,value)=>items.map(([id,label])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
const matrix=(values,label)=>`<div class="lg-matrix-scroll"><div class="lg-matrix" style="--columns:${values[0].length}" role="math" aria-label="${esc(label)}">${values.flatMap(row=>row.map(value=>`<span>${esc(complex(value))}</span>`)).join('')}</div></div>`;
export const foundationNames={u1:"U(1) · Continuous and discrete",representations:"One group, different representations · Spinors and vectors",interferometer:"Two-path phase interference in SU(2)"};
export const foundationDefaults={u1:{order:4,degrees:45,translation:.001},representations:{axis:'z',degrees:360},interferometer:{axis:'z',degrees:360,state:'up',branches:'single',phaseDegrees:0}};
export const foundationInputIds=['#lg-circle-order','#lg-translation','#lg-branches','#lg-phase'];
export const foundationPresets={
 'u1-circle-quarter':{experiment:'u1',input:{order:4,degrees:45,translation:.001}},
 'unitary-z-quarter':{experiment:'su2',input:{axis:'z',degrees:90,state:'up'}},
 'generators-xy':{experiment:'commutator',input:{group:'su2',a:1,b:2}},
 'spinor-y-quarter':{experiment:'su2',input:{axis:'y',degrees:90,state:'up'}},
 'su2-phase-single':{experiment:'interferometer',input:{axis:'z',degrees:360,state:'up',branches:'single',phaseDegrees:0}},
 'su2-center-actions':{experiment:'representations',input:{axis:'z',degrees:360}},
 'su3-t1-half':{experiment:'su3',input:{generator:1,degrees:180,state:1}},
 'su3-weight-phase':{experiment:'su3',input:{generator:3,degrees:90,state:'plus12'}}
};
export const lieGroupLabel=group=>({u1:'U(1)',su2:'SU(2)',su3:'SU(3)'})[group]||"Continuous group fundamentals";
export function foundationControls(experiment,input,angle){
 if(experiment==='u1')return `${angle}<div class="lg-presets"><button type="button" data-lg-preset="45">45°</button><button type="button" data-lg-preset="90">90°</button></div><label>Finite cyclic subgroup<select id="lg-circle-order">${options([[4,"C₄ · Four elements"],[8,"C₈ · Eight elements"]],input.order)}</select></label><label>Displacement (in lattice units, a=1)<input id="lg-translation" type="number" min="-8" max="8" step="any" value="${esc(input.translation)}"></label><p class="lg-hint">Test whether the selected angle belongs to Cₙ, then compare integer translations with arbitrary real translations. The finite display window is not the full group.</p>`;
 const axes=`<label>rotation axis<select id="lg-axis">${options([['x',"x-axis"],['y',"y-axis"],['z',"z-axis"]],input.axis)}</select></label>${angle}<div class="lg-presets"><button type="button" data-lg-preset="90">90°</button><button type="button" data-lg-preset="360">360°</button><button type="button" data-lg-preset="720">720°</button></div>`;
 if(experiment==='representations')return `${axes}<p class="lg-hint">Apply the same U to a two-component spinor and to the three-dimensional Pauli-vector space. Change the parameters and compare the two representation matrices and characters.</p>`;
 return `${axes}<label>Initial state<select id="lg-state">${options([['up','|↑⟩'],['plus','(1,1)ᵀ/√2'],['plus_i','(1,i)ᵀ/√2']],input.state)}</select></label><label>Where to apply the rotation<select id="lg-branches">${options([['single',"Rotate only the second arm"],['both',"Apply the same rotation to both arms"]],input.branches)}</select></label><label>Additional phase on the second arm (degrees)<input id="lg-phase" type="number" min="-1440" max="1440" step="any" value="${esc(input.phaseDegrees)}"></label><p class="lg-hint">Apply the transformation between equal splitting and recombination. Compare a 360° rotation on the second arm, a 720° rotation on that arm, and a 360° rotation on both arms.</p>`;
}
export function readFoundationPayload(experiment,$,number){
 const degrees=number('#lg-angle',-1440,1440),angle=degrees*Math.PI/180;
 if(experiment==='u1'){const order=number('#lg-circle-order',1,24,true),translation=number('#lg-translation',-8,8);return {input:{order,degrees,translation},payload:{lab:'lie',experiment,order,angle,translation}};}
 const axis=$('#lg-axis').value;if(!['x','y','z'].includes(axis))throw Error("Please select a valid axis and initial state.");
 if(experiment==='representations')return {input:{axis,degrees},payload:{lab:'lie',experiment,axis,angle}};
 const state=$('#lg-state').value,branches=$('#lg-branches').value,phaseDegrees=number('#lg-phase',-1440,1440);
 if(!['up','plus','plus_i'].includes(state)||!['single','both'].includes(branches))throw Error("Please select a valid axis and initial state.");
 return {input:{axis,degrees,state,branches,phaseDegrees},payload:{lab:'lie',experiment,axis,angle,state,branches,phase:phaseDegrees*Math.PI/180}};
}
const checkLabels={unitModulus:"Unit-modulus residual",subgroupClosure:"Cyclic-subgroup closure residual",spinorUnitarity:"Spinor unitarity residual",vectorOrthogonality:"Vector orthogonality residual",vectorDeterminant:"Vector determinant residual",probability:"Port-probability sum residual",portFormula:"Port-formula residual",unitarity:"unitary residual"};
const checks=result=>`<div class="lg-checks">${Object.entries(result.residuals||{}).map(([key,value])=>`<div><span>${esc(checkLabels[key]||key)}</span><code>${Number.isFinite(value)?value.toExponential(2):'—'}</code></div>`).join('')}</div>`;
export function foundationOutput(result){
 if(result.experiment==='u1'){
  const point=([x,y])=>[210+110*x,145-110*y],selected=point(result.selectedPoint);
  return `<svg class="lg-visual" viewBox="0 0 420 300" role="img" aria-label="Finite cyclic subgroup and continuous unit circle"><circle cx="210" cy="145" r="110" fill="none" stroke="#aac4b7" stroke-width="2"/>${result.circlePoints.map((value,index)=>{const p=point(value);return `<circle cx="${p[0]}" cy="${p[1]}" r="6" fill="#276951"><title>${index}</title></circle>`;}).join('')}<line x1="210" y1="145" x2="${selected[0]}" y2="${selected[1]}" stroke="#b67d32" stroke-width="3"/><circle cx="${selected[0]}" cy="${selected[1]}" r="8" fill="#b67d32"/><text x="210" y="286" text-anchor="middle" class="lg-svg-label">${svgMathText('C_'+result.order+' ⊂ U(1)')}</text></svg><div class="lg-state-facts"><p><span>Selected z(φ)</span><code>${esc(complex(result.element))}</code></p><p><span>In the finite subgroup Cₙ?</span><strong>${result.inFiniteSubgroup?"Yes":"No"}</strong></p><p><span>Is the displacement an integer translation?</span><strong>${result.inIntegerTranslations?"Yes":"No"}</strong></p></div><pre class="lg-formula">Integer translations: … −2, −1, 0, 1, 2 …
Selected real displacement: ${fmt(result.translation)}
Local real dimension of U(1): 1; complex representation dimension: 1; finite subgroup order: ${result.subgroupOrder}</pre>${checks(result)}`;
 }
 if(result.experiment==='representations')return `<div class="lg-matrix-pair"><section><h4>Spinor representation · Dimension 2</h4>${matrix(result.spinorMatrix,"Two-dimensional spinor representation of SU(2)")}<p>χ = ${esc(complex(result.spinorCharacter))}</p></section><section><h4>Vector representation · Dimension 3</h4>${matrix(result.vectorMatrix,"Three-dimensional vector representation of SU(2)")}<p>χ = ${fmt(result.vectorCharacter)}</p></section></div><div class="lg-state-facts"><p><span>Is the vector representation matrix I₃?</span><strong>${result.sameVectorAsIdentity?"Yes":"No"}</strong></p><p><span>Is the spinor representation matrix −I₂?</span><strong>${result.spinorIsNegativeIdentity?"Yes":"No"}</strong></p><p><span>Image of the z vector</span><code>${esc(vector(result.vectorImageOfZ))}</code></p></div><p>These are two actions of the same SU(2) element. The group's real dimension is 3, while the representation spaces have dimensions 2 and 3.</p>${checks(result)}`;
 return `<svg class="lg-visual" viewBox="0 0 420 220" role="img" aria-label="Output-port probabilities after recombining the two paths"><path d="M25 110 L90 50 H260 L330 110 L395 50 M90 170 H260 L330 110 L395 170 M25 110 L90 170" fill="none" stroke="#8da99a" stroke-width="3"/><text x="150" y="40" class="lg-svg-label">${result.branches==='both'?'U':'I'}</text><text x="150" y="195" class="lg-svg-label">U</text><text x="340" y="40" class="lg-svg-label">+</text><text x="340" y="198" class="lg-svg-label">−</text></svg><div class="lg-probabilities">${result.portProbabilities.map((value,index)=>`<div><span>${index===0?"+ port":"− port"}</span><progress max="1" value="${value}" aria-label="${index===0?"+ port probability":"− port probability"}"></progress><code>${fmt(value)}</code></div>`).join('')}</div><pre class="lg-formula">P± = [1 ± Re(e^(iφ)⟨Aψ|Bψ⟩)] / 2</pre><div class="lg-state-facts"><p><span>Four-dimensional path⊗spin state · Basis (a↑,a↓,b↑,b↓)</span><code>${esc(vector(result.pathState))}</code></p><p><span>Spin amplitudes at the + port</span><code>${esc(vector(result.portStates[0]))}</code></p><p><span>Spin amplitudes at the − port</span><code>${esc(vector(result.portStates[1]))}</code></p><p><span>Path overlap including the relative phase</span><code>${esc(complex(result.pathCoherence))}</code></p></div><p class="lg-hint">A and B act on the first and second arms, respectively. In single-arm mode, A=I and B=U. The squared norm of each port's spin-amplitude vector gives its probability. A zero-probability port has no defined conditional spin state.</p>${checks(result)}`;
}
